export const GLOSSARY_SHARD = Object.freeze({"cryptocurrency":{"slug":"cryptocurrency","cat":"basics","en":"Cryptocurrency","contentLocale":"id","term":"Cryptocurrency (aset kripto)","aka":["kripto","mata uang kripto","aset kripto","crypto"],"short":"Cryptocurrency atau aset kripto adalah aset digital yang dicatat di blockchain dan diamankan dengan kriptografi, sehingga bisa dikirim antarpengguna tanpa bank sebagai perantara.","body":[["Kepemilikan kripto ditentukan oleh siapa yang memegang ",["private key","private-key"]," untuk sebuah alamat. Saat Anda mengirim koin, Anda menandatangani transaksi dengan kunci itu, lalu jaringan memverifikasi dan mencatatnya. Contoh paling terkenal adalah ",["Bitcoin","bitcoin"],", disusul ",["Ethereum","ethereum"],", ",["stablecoin","stablecoin"]," seperti ",["USDT","usdt"],", dan ribuan ",["altcoin","altcoin"]," lainnya."],"Harga kripto ditentukan oleh penawaran dan permintaan di pasar, bukan oleh bank sentral. Karena itu harganya bisa naik atau turun puluhan persen dalam waktu singkat. Stablecoin adalah pengecualian karena dirancang mengikuti nilai mata uang seperti dolar AS.","Di Indonesia, kripto diperlakukan sebagai aset digital yang diperdagangkan, bukan alat pembayaran yang sah. Sejak Januari 2025 pengawasannya beralih dari Bappebti ke OJK. Aturan pajak dan perizinan bisa berbeda di setiap negara, jadi periksa ketentuan yang berlaku untuk Anda."],"example":"Misalkan Anda membeli aset kripto senilai Rp1.000.000 saat harganya Rp10.000 per koin, sehingga Anda mendapat 100 koin. Jika harga turun 30% menjadi Rp7.000, nilai simpanan Anda menjadi Rp700.000. Jika kemudian naik 50% dari Rp7.000 menjadi Rp10.500, nilainya Rp1.050.000. Perhatikan bahwa turun 30% lalu naik 50% hanya menghasilkan untung 5%, bukan 20%, karena persentase dihitung dari harga yang berbeda.","mistakes":["Menyimpan seluruh dana di satu koin kecil hanya karena harganya terlihat murah per unit.","Mengira kripto di exchange sama dengan kripto di dompet pribadi, padahal di exchange kunci dipegang oleh platform.","Membagikan seed phrase atau private key kepada orang yang mengaku sebagai admin atau customer service."],"faq":[{"q":"Apakah kripto legal di Indonesia?","a":"Perdagangan aset kripto di Indonesia legal melalui pedagang yang terdaftar dan diawasi OJK, tetapi kripto bukan alat pembayaran yang sah. Detail aturan bisa berubah, jadi cek informasi resmi terbaru."},{"q":"Apa beda kripto dan saham?","a":"Saham adalah bukti kepemilikan sebagian perusahaan. Kebanyakan kripto tidak memberi hak kepemilikan atas perusahaan, nilainya bergantung pada penggunaan jaringan dan permintaan pasar."}],"title":"Apa itu cryptocurrency? Arti aset kripto","description":"Arti cryptocurrency atau aset kripto, cara kepemilikannya bekerja, kenapa harganya bergejolak, dan posisinya di Indonesia.","related":[["blockchain","Blockchain","Blockchain adalah buku besar digital yang disimpan bersama oleh banyak komputer, di mana transaksi dikelompokkan ke dalam blok yang saling terhubung sehingga sangat sulit diubah setelah dicatat."],["bitcoin","Bitcoin (BTC)","Bitcoin (BTC) adalah aset kripto pertama yang diluncurkan pada 2009, berjalan di jaringan terdesentralisasi dengan proof of work dan jumlah maksimal 21 juta koin."],["altcoin","Altcoin","Altcoin adalah sebutan untuk semua aset kripto selain Bitcoin, mulai dari jaringan besar seperti Ethereum dan Solana hingga token kecil yang baru diluncurkan."],["stablecoin","Stablecoin","Stablecoin adalah aset kripto yang dirancang menjaga nilai stabil terhadap aset acuan, biasanya 1 dolar AS, seperti USDT dan USDC, sehingga dipakai sebagai alat tukar dan tempat parkir dana di pasar kripto."],["centralized-exchange","Centralized exchange (CEX)","Centralized exchange (CEX) adalah platform jual beli kripto yang dijalankan oleh sebuah perusahaan, yang menyimpan dana pengguna, mencocokkan order, dan biasanya mewajibkan verifikasi KYC."]],"lesson":{"id":"E01","slug":"can-i-buy-part-of-a-bitcoin","ep":1,"title":"Satu bitcoin harganya segitu. Apakah saya masih bisa beli sedikit?"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"smart-contract":{"slug":"smart-contract","cat":"basics","en":"Smart contract","contentLocale":"id","term":"Smart contract","aka":["kontrak pintar"],"short":"Smart contract adalah program yang disimpan dan dijalankan di blockchain, yang otomatis mengeksekusi aturan tertentu ketika syaratnya terpenuhi, tanpa perlu perantara.","body":[["Bayangkan mesin penjual minuman: masukkan uang yang cukup, pilih tombol, dan minuman keluar tanpa kasir. Smart contract bekerja serupa. Kodenya dipublikasikan ke ",["blockchain","blockchain"]," seperti ",["Ethereum","ethereum"],", Solana, atau BNB Chain, lalu siapa pun bisa berinteraksi dengannya sesuai aturan yang tertulis."],["Hampir semua aplikasi ",["DeFi","defi"],", token ERC-20, ",["NFT","nft"],", dan bridge berjalan di atas smart contract. Setiap interaksi membutuhkan ",["biaya gas","gas-fee"],". Karena kodenya publik, siapa pun bisa memeriksanya, tetapi itu juga berarti celah keamanan bisa ditemukan dan dieksploitasi oleh peretas."],["Saat Anda memberi izin (approve) pada sebuah kontrak, kontrak itu bisa memindahkan token tertentu dari dompet Anda sampai batas yang Anda setujui. Karena itu, berhati-hatilah terhadap ",["situs palsu","phishing"]," yang meminta approve tak terbatas."]],"example":"Misalkan Anda menukar 1.000 USDC ke ETH di DEX. Langkah pertama adalah approve agar kontrak DEX boleh memakai USDC Anda, misalnya dengan biaya gas 0,0005 ETH. Langkah kedua adalah swap itu sendiri dengan biaya 0,0012 ETH. Kontrak mengambil 1.000 USDC, menghitung harga dari pool, dan mengirim sekitar 0,33 ETH ke dompet Anda dalam satu transaksi, tanpa ada petugas yang terlibat.","mistakes":["Memberi approve tak terbatas ke kontrak yang tidak dikenal lalu lupa mencabutnya.","Menganggap kontrak yang sudah diaudit pasti bebas celah.","Mengira transaksi smart contract yang salah bisa dibatalkan oleh pembuatnya."],"faq":[{"q":"Apakah smart contract bisa diubah?","a":"Tergantung desainnya. Ada kontrak yang tidak bisa diubah sama sekali, dan ada yang memakai pola upgrade sehingga pengembang dapat memperbaruinya, yang juga berarti ada pihak yang memegang kendali."},{"q":"Bagaimana cara mencabut izin smart contract?","a":"Anda bisa mencabut approve lewat fitur di dompet atau alat revoke di block explorer. Pencabutan itu sendiri juga memerlukan biaya gas."}],"title":"Apa itu smart contract? Arti dan contohnya","description":"Arti smart contract, cara program di blockchain menjalankan aturan otomatis, dan risiko approve yang perlu Anda waspadai.","related":[["ethereum","Ethereum (ETH)","Ethereum adalah blockchain yang bisa menjalankan smart contract, dan ETH adalah koin aslinya yang dipakai untuk membayar biaya gas dan untuk staking."],["defi","DeFi (keuangan terdesentralisasi)","DeFi adalah layanan keuangan yang berjalan di atas smart contract di blockchain, seperti swap, pinjam-meminjam, dan staking, tanpa perantara seperti bank atau exchange terpusat."],["token-approval","Token approval (izin token)","Token approval adalah izin yang Anda berikan dari dompet kepada smart contract agar kontrak tersebut boleh memindahkan token tertentu milik Anda hingga batas jumlah yang disetujui."],["oracle","Oracle blockchain","Oracle blockchain adalah layanan yang membawa data dari luar blockchain, seperti harga aset, ke dalam smart contract agar kontrak bisa mengambil keputusan berdasarkan data tersebut."],["gas-fee","Gas fee (biaya gas)","Gas fee atau biaya gas adalah biaya yang Anda bayar kepada jaringan blockchain untuk memproses transaksi atau menjalankan smart contract, biasanya dalam coin asli jaringan tersebut."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"gas-fee":{"slug":"gas-fee","cat":"basics","en":"Gas fee","contentLocale":"id","term":"Gas fee (biaya gas)","aka":["biaya gas","gas","network fee"],"short":"Gas fee atau biaya gas adalah biaya yang Anda bayar kepada jaringan blockchain untuk memproses transaksi atau menjalankan smart contract, biasanya dalam coin asli jaringan tersebut.","body":[["Di ",["Ethereum","ethereum"],", biaya gas dihitung dari jumlah unit gas yang dipakai transaksi dikali harga gas per unit, biasanya dalam gwei (0,000000001 ETH). Transfer ETH sederhana memakai 21.000 unit gas, sedangkan swap di ",["DEX","dex"]," atau mint ",["NFT","nft"]," memakai jauh lebih banyak karena komputasinya lebih rumit."],["Harga gas naik saat jaringan ramai karena pengguna bersaing agar transaksinya diproses lebih dulu. Sejak pembaruan EIP-1559, biaya terdiri dari base fee yang dibakar dan priority fee atau tip untuk ",["validator","validator"],". Jaringan lain seperti Solana, TRON, atau ",["layer 2","layer-2"]," punya model biaya sendiri, umumnya jauh lebih murah."],["Di exchange, Anda biasanya tidak membayar gas langsung, melainkan ",["biaya penarikan","withdrawal-fee"]," yang ditetapkan platform. Biaya ini bisa berbeda dengan gas sebenarnya dan bergantung pada jaringan yang Anda pilih."]],"example":"Misalkan Anda mengirim ETH ke teman. Transfer memakai 21.000 unit gas, base fee 15 gwei, dan tip 1 gwei, total 16 gwei per unit. Biayanya 21.000 x 16 = 336.000 gwei, atau 0,000336 ETH. Jika ETH bernilai 3.500 USDT, biaya transfer sekitar 1,18 USDT. Jika jaringan ramai dan base fee naik menjadi 60 gwei, biaya menjadi 21.000 x 61 = 1.281.000 gwei, atau sekitar 4,48 USDT.","mistakes":["Menyetel batas gas terlalu rendah sehingga transaksi gagal, padahal biaya gas yang terpakai tetap hilang.","Mengosongkan seluruh saldo ETH sehingga tidak bisa memindahkan token lain di jaringan Ethereum.","Menyamakan biaya penarikan exchange dengan biaya gas jaringan."],"faq":[{"q":"Kenapa biaya gas kadang sangat mahal?","a":"Biaya gas naik ketika banyak orang bertransaksi bersamaan, misalnya saat peluncuran token populer. Anda bisa menunggu jaringan sepi atau memakai layer 2."},{"q":"Apakah biaya gas kembali jika transaksi gagal?","a":"Umumnya tidak. Gas yang sudah dipakai untuk memproses transaksi tetap dibayar meski transaksinya gagal."}],"title":"Apa itu gas fee? Arti biaya gas di kripto","description":"Pelajari arti gas fee, cara menghitung biaya gas dalam gwei, kenapa biayanya naik turun, dan cara menghemat biaya transaksi.","related":[["layer-2","Layer 2 (L2)","Layer 2 (L2) adalah jaringan yang dibangun di atas blockchain layer 1, memproses transaksi di luar jaringan utama lalu menyetor ringkasannya ke L1 agar lebih cepat dan murah."],["mempool","Mempool","Mempool adalah ruang tunggu tempat transaksi yang sudah disiarkan tetapi belum masuk blok disimpan sementara oleh node, sebelum dipilih oleh penambang atau validator."],["withdrawal-fee","Biaya penarikan (withdrawal fee)","Biaya penarikan adalah biaya yang dipotong bursa saat Anda menarik kripto ke alamat lain atau menarik rupiah ke rekening bank, biasanya berupa jumlah tetap per transaksi yang bergantung pada koin dan jaringan."],["ethereum","Ethereum (ETH)","Ethereum adalah blockchain yang bisa menjalankan smart contract, dan ETH adalah koin aslinya yang dipakai untuk membayar biaya gas dan untuk staking."],["smart-contract","Smart contract","Smart contract adalah program yang disimpan dan dijalankan di blockchain, yang otomatis mengeksekusi aturan tertentu ketika syaratnya terpenuhi, tanpa perlu perantara."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Sebelum transfer: jangan tebak-tebak hal-hal ini"},"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"bull-market":{"slug":"bull-market","cat":"basics","en":"Bull market","contentLocale":"id","term":"Bull market (pasar bullish)","aka":["bullish","bull run","pasar naik"],"short":"Bull market adalah periode ketika harga aset di pasar cenderung naik secara berkelanjutan selama berminggu-minggu hingga bertahun-tahun, disertai sentimen optimis dan minat beli yang tinggi.","body":[["Istilah ini berasal dari banteng yang menyerang dengan menanduk ke atas. Dalam bull market, harga membentuk puncak dan lembah yang makin tinggi, ",["volume perdagangan","trading-volume"]," naik, dan banyak pengguna baru masuk ke pasar. Kata bullish juga dipakai untuk pandangan bahwa harga akan naik."],["Bull market kripto sering diiringi ",["rekor harga","all-time-high"]," tertinggi baru (ATH), lonjakan ",["altcoin","altcoin"],", dan maraknya ",["FOMO","fomo"],". Namun di dalam tren naik pun tetap ada koreksi tajam 20% sampai 30% yang bisa menghapus posisi dengan ",["leverage","leverage"]," tinggi."],["Tidak ada definisi resmi kapan bull market dimulai atau selesai. Sebagian trader memakai patokan kenaikan 20% dari titik terendah, yang lain melihat struktur tren atau rata-rata pergerakan jangka panjang. Yang penting adalah tetap mengelola ",["ukuran posisi","position-sizing"]," dan rencana keluar."]],"example":"Misalkan BTC naik dari 30.000 USDT ke 60.000 USDT dalam setahun, kenaikan 100%. Di tengah jalan, harga sempat turun dari 52.000 ke 41.600 USDT, koreksi 20%. Trader yang membuka posisi long dengan leverage 5x di 52.000 USDT akan kehilangan sekitar 100% margin pada penurunan sebesar itu, sehingga terkena likuidasi meski tren besar tetap naik.","mistakes":["Menganggap harga hanya bisa naik selama bull market lalu menaikkan leverage.","Membeli di puncak karena takut ketinggalan tanpa rencana take profit atau stop loss.","Mengira semua altcoin akan ikut naik setinggi aset-aset besar."],"faq":[{"q":"Apa arti bullish dalam kripto?","a":"Bullish berarti memperkirakan atau melihat harga cenderung naik. Kebalikannya adalah bearish."},{"q":"Bagaimana mengetahui pasar sedang bull market?","a":"Biasanya terlihat dari tren harga yang membuat puncak dan lembah makin tinggi dalam jangka panjang serta volume yang meningkat. Tidak ada satu indikator yang pasti."}],"title":"Apa itu bull market? Arti bullish di kripto","description":"Arti bull market dan bullish di kripto, ciri pasar naik, dan kenapa koreksi tajam tetap terjadi di tengah tren naik.","related":[["bear-market","Bear market (pasar bearish)","Bear market adalah periode ketika harga aset di pasar cenderung turun secara berkelanjutan, biasanya 20% atau lebih dari puncaknya, disertai sentimen pesimis dan volume yang menurun."],["fomo","FOMO (fear of missing out)","FOMO atau fear of missing out adalah rasa takut ketinggalan keuntungan yang mendorong trader membeli secara impulsif setelah harga sudah naik tajam."],["all-time-high","All-time high (ATH)","All-time high (ATH) adalah harga tertinggi yang pernah dicapai sebuah aset sejak mulai diperdagangkan."],["fear-and-greed-index","Fear and Greed Index (indeks ketakutan dan keserakahan)","Fear and Greed Index adalah indikator sentimen pasar kripto berskala 0 sampai 100, di mana angka rendah menunjukkan ketakutan ekstrem dan angka tinggi menunjukkan keserakahan ekstrem."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"take-profit":{"slug":"take-profit","cat":"trading","en":"Take-profit order","contentLocale":"id","term":"Take profit","aka":["TP","order take profit","ambil untung"],"short":"Take profit adalah order otomatis untuk menutup posisi ketika harga mencapai target keuntungan yang sudah Anda tetapkan.","body":[["Seperti ",["stop loss","stop-loss"],", take profit memiliki harga pemicu. Saat harga mencapai level itu, exchange menutup sebagian atau seluruh posisi dengan ",["market order","market-order"]," atau ",["limit order","limit-order"],". Take profit membantu Anda mengunci untung tanpa harus terus memantau layar."],"Banyak trader membagi take profit menjadi beberapa level, misalnya menutup 50% di target pertama dan sisanya di target kedua. Cara ini menyeimbangkan antara mengamankan untung dan memberi ruang jika tren berlanjut.",["Target take profit sebaiknya ditentukan bersama stop loss untuk menghitung rasio risiko dan imbalan. Exchange menyediakan take profit langsung di form order, sebagai order ",["OCO","oco-order"],", atau sebagai pengaturan TP/SL pada posisi futures. Nama dan opsi pemicunya bisa berbeda di tiap platform."]],"example":["Misalkan Anda membeli 2 ",["ETH","ethereum"]," di 2.800 ",["USDT","usdt"]," dengan stop loss di 2.660 USDT, risiko 140 USDT per ETH atau 280 USDT total. Anda memasang take profit pertama untuk 1 ETH di 3.080 USDT dan kedua untuk 1 ETH di 3.220 USDT. Jika keduanya terisi, keuntungan Anda 280 + 420 = 700 USDT sebelum biaya, atau 2,5 kali risiko awal."],"mistakes":["Tidak memasang target sama sekali sehingga keuntungan berubah menjadi kerugian saat harga berbalik.","Menetapkan take profit terlalu dekat sementara stop loss jauh, sehingga rasio risiko dan imbalan buruk.","Membatalkan take profit di tengah jalan karena serakah tanpa alasan dari rencana awal."],"faq":[{"q":"Apa arti TP dalam trading?","a":"TP adalah singkatan take profit, yaitu level harga atau order untuk mengambil keuntungan dengan menutup posisi."},{"q":"Apakah sebaiknya take profit sekaligus atau bertahap?","a":"Keduanya bisa. Take profit bertahap mengunci sebagian untung lebih awal dan tetap memberi peluang jika harga terus bergerak sesuai arah Anda."}],"title":"Apa itu take profit (TP)? Arti dan cara memasangnya","description":"Pelajari arti take profit, cara memasang target keuntungan bertahap, dan hubungannya dengan stop loss serta rasio risiko imbalan.","related":[["stop-loss","Stop loss","Stop loss adalah order otomatis untuk menutup posisi ketika harga bergerak melawan Anda sampai level tertentu, agar kerugian dibatasi sesuai rencana."],["oco-order","OCO order (one cancels the other)","OCO order adalah pasangan dua order, biasanya take profit dan stop loss, di mana ketika salah satunya tereksekusi, order lainnya otomatis dibatalkan."],["risk-reward-ratio","Rasio risk-reward (risk-reward ratio)","Rasio risk-reward adalah perbandingan antara potensi kerugian sebuah trade (jarak ke stop loss) dan potensi keuntungannya (jarak ke take profit), misalnya 1:2."],["limit-order","Limit order","Limit order adalah perintah membeli atau menjual di harga tertentu yang Anda tetapkan atau lebih baik, sehingga harga terkendali tetapi order belum tentu tereksekusi."]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"Take-profit dan stop-loss adalah rencana, bukan asuransi"},"coin":null,"tool":null,"cta":false},"margin-trading":{"slug":"margin-trading","cat":"derivatives","en":"Margin trading","contentLocale":"id","term":"Margin trading","aka":["trading margin","spot margin","margin"],"short":"Margin trading adalah cara trading dengan meminjam dana dari exchange menggunakan aset Anda sebagai jaminan, sehingga Anda bisa membuka posisi lebih besar dari saldo sendiri atau menjual aset yang dipinjam.","body":[["Di ",["pasar spot","spot-trading"]," margin, Anda benar-benar meminjam aset. Untuk long, Anda meminjam ",["USDT","usdt"]," lalu membeli koin. Untuk short, Anda meminjam koin lalu menjualnya, berharap membelinya kembali lebih murah. Pinjaman ini dikenai bunga per jam atau per hari, dan tarifnya berubah sesuai permintaan."],["Istilah margin juga dipakai di futures, tetapi mekanismenya berbeda: di futures tidak ada pinjaman aset, melainkan kontrak dengan margin sebagai jaminan dan ",["funding rate","funding-rate"]," sebagai biaya. Banyak exchange besar seperti Binance, OKX, dan Bybit menawarkan kedua produk ini dengan aturan yang berbeda."],["Risiko utamanya sama: jika nilai jaminan turun di bawah batas tertentu, exchange bisa melikuidasi posisi Anda untuk melunasi pinjaman. Pilih ",["mode isolated","isolated-margin"]," atau cross dengan sadar."]],"example":["Anda punya 1.000 USDT di akun margin dan memilih ",["leverage","leverage"]," 3x. Anda meminjam 2.000 USDT lalu membeli ",["ETH","ethereum"]," senilai 3.000 USDT di harga 2.500, total 1,2 ETH. Bunga pinjaman misalnya 0,002% per jam, jadi sekitar 0,96 USDT per hari. Jika ETH naik 10% ke 2.750, nilai ETH Anda 3.300 USDT; setelah melunasi 2.000 USDT pinjaman, sisa 1.300 USDT, untung sekitar 300 USDT dikurangi bunga dan biaya."],"mistakes":["Lupa bahwa bunga pinjaman terus berjalan selama posisi terbuka, meski harga diam.","Menyamakan margin trading spot dengan futures, padahal biaya dan cara likuidasinya berbeda.","Meninggalkan posisi margin tanpa stop loss saat pasar bergejolak."],"faq":[{"q":"Apa beda margin trading dan futures?","a":"Margin trading meminjam aset nyata dan membayar bunga, sedangkan futures memakai kontrak tanpa pinjaman aset dan biasanya dikenai funding rate. Keduanya memakai jaminan dan bisa dilikuidasi."},{"q":"Apakah margin trading bisa dipakai untuk short?","a":"Bisa. Anda meminjam koin, menjualnya, lalu membelinya kembali untuk mengembalikan pinjaman. Jika harga turun, selisihnya menjadi keuntungan Anda."}],"title":"Apa itu margin trading kripto? Arti dan cara kerjanya","description":"Pelajari margin trading di kripto: cara meminjam untuk long atau short, bunga pinjaman, beda dengan futures, dan risiko likuidasi.","related":[["leverage","Leverage (daya ungkit)","Leverage adalah fitur yang memungkinkan Anda membuka posisi lebih besar dari modal yang disetor, misalnya 10x berarti margin 100 USDT mengendalikan posisi senilai 1.000 USDT."],["initial-margin","Margin awal (initial margin)","Margin awal adalah jumlah jaminan minimum yang harus Anda setor untuk membuka posisi dengan leverage, biasanya sama dengan nilai posisi dibagi leverage yang dipilih."],["maintenance-margin","Maintenance margin (margin pemeliharaan)","Maintenance margin adalah jumlah margin minimum yang harus tetap ada dalam posisi agar tidak dilikuidasi; jika ekuitas posisi turun di bawah batas ini, exchange mulai menutup posisi Anda."],["liquidation","Likuidasi (liquidation)","Likuidasi adalah penutupan paksa posisi leverage oleh exchange ketika margin yang tersisa tidak lagi cukup untuk memenuhi maintenance margin, sehingga sebagian besar atau seluruh margin posisi itu hilang."],["cross-margin","Margin silang (cross margin)","Margin silang adalah mode margin di mana seluruh saldo yang tersedia di akun futures dipakai bersama sebagai jaminan untuk semua posisi terbuka, sehingga posisi lebih sulit dilikuidasi tetapi seluruh saldo ikut dipertaruhkan."]],"lesson":{"id":"E19","slug":"what-leverage-does","ep":19,"title":"Leverage 10x: lebih banyak uang, atau lebih banyak risiko?"},"coin":null,"tool":null,"cta":false},"non-custodial-wallet":{"slug":"non-custodial-wallet","cat":"wallets-security","en":"Non-custodial (self-custody) wallet","contentLocale":"id","term":"Dompet non-kustodian (self-custody wallet)","aka":["non-custodial wallet","dompet self-custody","self-custody wallet","dompet pribadi"],"short":"Dompet non-kustodian adalah dompet kripto di mana hanya Anda yang memegang private key, sehingga tidak ada pihak lain yang bisa memindahkan, membekukan, atau memulihkan aset Anda.","body":[["Saat Anda menyimpan kripto di exchange, platform itulah yang memegang kunci, dan Anda hanya melihat saldo di sistem mereka. Pada dompet non-kustodian seperti MetaMask, Phantom, Trust Wallet, atau ",["hardware wallet","hardware-wallet"],", kunci dibuat di perangkat Anda sendiri dan dicadangkan dengan ",["seed phrase (frasa pemulihan)","seed-phrase"]," yang hanya Anda ketahui."],["Keuntungannya adalah kendali penuh. Anda tidak bergantung pada kesehatan keuangan exchange, jadwal penarikan, atau pembekuan akun. Anda juga bisa langsung terhubung ke aplikasi ",["DeFi","defi"],", ",["DEX","dex"],", dan marketplace ",["NFT","nft"],"."],"Konsekuensinya, semua tanggung jawab ada di tangan Anda. Tidak ada tombol lupa kata sandi. Jika seed phrase dan perangkat hilang, aset tidak bisa diakses lagi. Jika orang lain mendapatkan seed phrase tersebut, mereka bisa menguras dompet tanpa izin siapa pun. Karena itu banyak orang memakai keduanya: exchange untuk trading aktif, dompet pribadi untuk simpanan jangka panjang."],"example":["Misalnya Anda membeli 200 ",["USDT","usdt"]," di exchange lalu menariknya ke dompet non-kustodian di jaringan Tron. Exchange memotong biaya penarikan, katakanlah 1 USDT, sehingga yang tiba 199 USDT. Sejak saat itu exchange tidak bisa lagi membekukan saldo tersebut. Setahun kemudian ponsel Anda rusak. Anda memasang aplikasi dompet di ponsel baru, memasukkan 12 kata seed phrase, dan 199 USDT muncul kembali, karena aset tercatat di blockchain, bukan di ponsel."],"mistakes":["Menyimpan seed phrase sebagai tangkapan layar atau di cloud, tempat malware dan kebocoran data bisa menemukannya.","Mengira layanan pelanggan aplikasi dompet bisa mengembalikan aset jika seed phrase hilang.","Menandatangani transaksi di situs yang tidak dikenal tanpa membaca izin apa yang sedang diberikan."],"faq":[{"q":"Apa beda dompet kustodian dan non-kustodian?","a":"Pada dompet kustodian, pihak ketiga seperti exchange menyimpan kunci dan mengelola aset Anda. Pada dompet non-kustodian, Anda sendiri yang memegang kunci dan satu-satunya yang bisa menandatangani transaksi."},{"q":"Apakah dompet non-kustodian lebih aman daripada exchange?","a":"Risiko exchange bangkrut atau membekukan akun hilang, tetapi risiko kehilangan atau pencurian seed phrase berpindah ke Anda. Keamanannya sangat bergantung pada cara Anda menyimpan kunci."}],"title":"Apa itu dompet non-kustodian? Arti self-custody kripto","description":"Pelajari arti dompet non-kustodian, cara kerja self-custody, dan risiko yang Anda tanggung saat menyimpan private key sendiri.","related":[["custodial-wallet","Dompet kustodian (custodial wallet)","Dompet kustodian adalah dompet kripto di mana pihak ketiga, biasanya exchange, menyimpan dan mengelola private key untuk Anda, sehingga Anda mengakses aset lewat akun, bukan lewat kunci sendiri."],["seed-phrase","Seed phrase (frasa pemulihan)","Seed phrase adalah rangkaian 12 atau 24 kata acak yang menjadi cadangan utama dompet kripto, karena dari kata-kata inilah semua private key dan alamat dompet Anda bisa dibuat ulang."],["private-key","Private key (kunci privat)","Private key adalah angka rahasia yang membuktikan kepemilikan sebuah alamat kripto dan dipakai untuk menandatangani transaksi, sehingga siapa pun yang memegangnya bisa memindahkan aset di alamat itu."],["hardware-wallet","Hardware wallet (dompet perangkat keras)","Hardware wallet adalah perangkat fisik khusus yang menyimpan private key secara offline dan menandatangani transaksi di dalam perangkat, sehingga kunci tidak pernah terekspos ke komputer atau ponsel."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Di mana koin saya? Bursa vs dompet"},"coin":null,"tool":null,"cta":false},"multisig-wallet":{"slug":"multisig-wallet","cat":"wallets-security","en":"Multisig wallet","contentLocale":"id","term":"Dompet multisig (multi-signature)","aka":["multisig","multi-signature wallet","dompet multi-tanda tangan","Safe"],"short":"Dompet multisig adalah dompet yang membutuhkan beberapa tanda tangan dari kunci berbeda, misalnya 2 dari 3, sebelum sebuah transaksi bisa dijalankan.","body":[["Dompet biasa hanya punya satu ",["private key","private-key"],", sehingga satu kunci yang bocor berarti seluruh dana hilang. Pada multisig, aturan seperti 2 dari 3 atau 3 dari 5 ditetapkan sejak awal. Satu kunci yang dicuri tidak cukup untuk memindahkan dana, dan satu kunci yang hilang tidak membuat dana terkunci selamanya."],["Multisig banyak dipakai oleh ",["DAO","dao"],", tim proyek, perusahaan, dan exchange untuk mengelola kas. Di ",["Ethereum","ethereum"]," dan jaringan EVM, Safe (dulu Gnosis Safe) adalah contoh ",["smart contract","smart-contract"]," multisig yang populer. ",["Bitcoin","bitcoin"]," juga mendukung multisig secara bawaan."],["Bagi individu, multisig bisa dipakai untuk simpanan besar, misalnya dengan tiga ",["hardware wallet","hardware-wallet"]," yang disimpan di lokasi berbeda. Kekurangannya, pengaturannya lebih rumit, biaya transaksinya bisa lebih tinggi, dan Anda harus mendokumentasikan konfigurasi dengan baik agar pemulihan tetap mungkin."]],"example":"Sebuah komunitas menyimpan kas 50.000 USDC di dompet multisig 2 dari 3. Kunci dipegang bendahara, ketua, dan satu anggota senior. Untuk membayar vendor 2.000 USDC, bendahara membuat transaksi dan menandatanganinya, lalu ketua ikut menandatangani. Dengan 2 tanda tangan, transaksi dijalankan. Ketika laptop bendahara terkena malware, penyerang hanya mendapatkan 1 kunci dan tidak bisa memindahkan 50.000 USDC tersebut.","mistakes":["Menyimpan beberapa kunci multisig di perangkat atau lokasi yang sama.","Tidak mencatat konfigurasi dompet, sehingga pemulihan sulit dilakukan.","Menandatangani transaksi multisig tanpa memverifikasi detailnya karena percaya penandatangan lain sudah memeriksa."],"faq":[{"q":"Apa arti 2 dari 3 pada multisig?","a":"Ada 3 kunci yang terdaftar, dan setiap transaksi memerlukan tanda tangan dari minimal 2 di antaranya."},{"q":"Apakah multisig cocok untuk pemula?","a":"Untuk jumlah kecil biasanya tidak perlu. Multisig lebih bermanfaat untuk dana besar atau dana bersama, dan sebaiknya dipelajari dulu dengan jumlah uji coba kecil."}],"title":"Apa itu dompet multisig? Arti multi-signature wallet","description":"Pelajari cara kerja dompet multisig, arti aturan 2 dari 3, serta kelebihan dan kekurangannya untuk menyimpan kripto.","related":[["private-key","Private key (kunci privat)","Private key adalah angka rahasia yang membuktikan kepemilikan sebuah alamat kripto dan dipakai untuk menandatangani transaksi, sehingga siapa pun yang memegangnya bisa memindahkan aset di alamat itu."],["cold-wallet","Cold wallet (cold storage)","Cold wallet adalah cara menyimpan kripto dengan private key yang dibuat dan disimpan sepenuhnya offline, sehingga tidak bisa dijangkau peretas lewat internet."],["dao","DAO (organisasi otonom terdesentralisasi)","DAO adalah organisasi yang aturan dan keputusannya dijalankan lewat smart contract dan voting anggota, biasanya pemegang governance token, bukan melalui struktur manajemen tradisional."],["non-custodial-wallet","Dompet non-kustodian (self-custody wallet)","Dompet non-kustodian adalah dompet kripto di mana hanya Anda yang memegang private key, sehingga tidak ada pihak lain yang bisa memindahkan, membekukan, atau memulihkan aset Anda."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Di mana koin saya? Bursa vs dompet"},"coin":null,"tool":null,"cta":false},"dao":{"slug":"dao","cat":"defi","en":"DAO (decentralized autonomous organization)","contentLocale":"id","term":"DAO (organisasi otonom terdesentralisasi)","aka":["decentralized autonomous organization","organisasi otonom terdesentralisasi","DAO"],"short":"DAO adalah organisasi yang aturan dan keputusannya dijalankan lewat smart contract dan voting anggota, biasanya pemegang governance token, bukan melalui struktur manajemen tradisional.","body":[["Dalam DAO, anggota mengajukan proposal, misalnya mengubah fee protokol, mendanai pengembang, atau menambah aset baru. Pemegang token memberikan suara, dan jika proposal lolos sesuai kuorum serta ambang yang ditetapkan, keputusan dijalankan, kadang otomatis lewat kontrak, kadang oleh ",["dompet multisig","multisig-wallet"]," yang ditunjuk."],["Banyak protokol ",["DeFi","defi"]," besar dikelola dengan model ini, seperti Uniswap, Aave, dan MakerDAO (kini Sky). DAO sering memegang kas dalam jumlah besar yang hanya bisa dipakai melalui voting."],"Dalam praktiknya, desentralisasi DAO beragam. Partisipasi voting sering rendah, suara bisa terkonsentrasi pada beberapa pemegang besar atau delegasi, dan tim inti masih punya pengaruh besar. Status hukum DAO juga berbeda di tiap negara. Bagi pemegang token, memahami siapa yang sebenarnya mengendalikan keputusan sama pentingnya dengan membaca proposalnya."],"example":["Misalnya sebuah DAO memiliki 100 juta ",["governance token","governance-token"]," dengan aturan kuorum 4 juta suara dan proposal lolos jika lebih dari 50% suara setuju. Proposal untuk menyalurkan 200.000 ",["USDC","usdc"]," dari kas ke tim audit mendapat 5 juta suara: 3,2 juta setuju dan 1,8 juta menolak. Kuorum tercapai dan 64% suara setuju, sehingga proposal lolos. Setelah masa tunggu, dompet multisig DAO mengirim 200.000 USDC tersebut."],"mistakes":["Mengira memegang governance token berarti memiliki hak atas keuntungan atau kas DAO.","Menganggap semua DAO benar-benar terdesentralisasi tanpa memeriksa distribusi suara.","Menandatangani pesan voting di situs tiruan yang sebenarnya meminta approval token."],"faq":[{"q":"Bagaimana cara ikut voting di DAO?","a":"Biasanya dengan memegang governance token di dompet dan memilih melalui platform voting resmi proyek, atau mendelegasikan suara ke orang lain."},{"q":"Apakah DAO punya pemimpin?","a":"Tidak ada direktur dalam arti tradisional, tetapi tim inti, yayasan, atau delegasi besar sering memiliki pengaruh besar terhadap arah proyek."}],"title":"Apa itu DAO? Arti organisasi otonom terdesentralisasi","description":"Pelajari arti DAO, cara voting dan proposal bekerja, contoh DAO di DeFi, serta keterbatasan desentralisasinya dalam praktik.","related":[["governance-token","Governance token (token tata kelola)","Governance token adalah token yang memberi pemegangnya hak suara atas keputusan sebuah protokol atau DAO, seperti perubahan parameter, penggunaan kas, atau peningkatan kontrak."],["multisig-wallet","Dompet multisig (multi-signature)","Dompet multisig adalah dompet yang membutuhkan beberapa tanda tangan dari kunci berbeda, misalnya 2 dari 3, sebelum sebuah transaksi bisa dijalankan."],["smart-contract","Smart contract","Smart contract adalah program yang disimpan dan dijalankan di blockchain, yang otomatis mengeksekusi aturan tertentu ketika syaratnya terpenuhi, tanpa perlu perantara."],["defi","DeFi (keuangan terdesentralisasi)","DeFi adalah layanan keuangan yang berjalan di atas smart contract di blockchain, seperti swap, pinjam-meminjam, dan staking, tanpa perantara seperti bank atau exchange terpusat."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"apr-vs-apy":{"slug":"apr-vs-apy","cat":"defi","en":"APR vs APY","contentLocale":"id","term":"APR vs APY","aka":["APR","APY","bunga tahunan","imbal hasil tahunan"],"short":"APR adalah tingkat imbal hasil tahunan tanpa bunga berbunga, sedangkan APY sudah memperhitungkan efek bunga berbunga (compounding), sehingga APY selalu sama atau lebih tinggi dari APR dengan tingkat dasar yang sama.","body":["APR (annual percentage rate) menghitung imbal hasil seolah reward tidak diinvestasikan kembali. APY (annual percentage yield) mengasumsikan reward ditambahkan ke modal secara berkala, harian, mingguan, atau bulanan, sehingga reward berikutnya dihitung dari modal yang lebih besar.",["Di produk earn exchange, ",["staking","staking"],", dan ",["DeFi","defi"],", angka yang ditampilkan bisa APR atau APY, dan biasanya bersifat variabel. Platform yang ingin angkanya terlihat lebih besar cenderung menampilkan APY. Selalu periksa label, frekuensi compounding, dan apakah reward dibayar dalam token yang sama atau token lain."],["APR dan APY juga hanya mengukur jumlah token, bukan nilai dalam rupiah atau dolar. APY 10% untuk sebuah token tidak berarti apa-apa jika harga token itu turun 30%. Konsep yang sama berlaku untuk biaya: ",["funding rate","funding-rate"]," per 8 jam atau bunga pinjaman harian bisa terlihat kecil tetapi besar jika disetahunkan."]],"example":["Misalnya Anda menaruh 10.000 ",["USDT","usdt"]," di produk dengan APR 12%. Tanpa compounding, setelah setahun Anda mendapat 1.200 USDT. Jika reward 1% dibayar dan ditambahkan ke modal setiap bulan, hasilnya 10.000 × 1,01 pangkat 12 ≈ 11.268 USDT, artinya APY sekitar 12,68%. Selisih 68 USDT berasal dari bunga atas bunga. Angka ini mengasumsikan tingkat bunga tetap selama setahun, padahal di kripto tingkatnya biasanya berubah."],"mistakes":["Membandingkan APR satu platform dengan APY platform lain secara langsung.","Mengira APY yang ditampilkan adalah imbal hasil yang dijamin untuk setahun penuh.","Lupa bahwa reward dalam token yang harganya turun bisa membuat hasil riil negatif."],"faq":[{"q":"Mana yang lebih tinggi, APR atau APY?","a":"Dengan tingkat dasar yang sama, APY sama atau lebih tinggi karena memperhitungkan bunga berbunga. Semakin sering compounding, semakin besar selisihnya."},{"q":"Bagaimana mengubah APR menjadi APY?","a":"Gunakan rumus APY = (1 + APR ÷ n) pangkat n − 1, dengan n jumlah periode compounding per tahun, misalnya 12 untuk bulanan atau 365 untuk harian."}],"title":"APR vs APY: apa bedanya di kripto?","description":"Pelajari beda APR dan APY, cara menghitung efek compounding, dan cara membaca angka imbal hasil di produk staking atau earn.","related":[["staking","Staking","Staking adalah mengunci koin di jaringan proof of stake untuk membantu memvalidasi transaksi dan mengamankan jaringan, dengan imbalan berupa reward dalam koin yang sama."],["yield-farming","Yield farming","Yield farming adalah strategi menempatkan aset kripto di berbagai protokol DeFi, seperti liquidity pool atau lending, untuk mendapatkan fee, bunga, dan token insentif."],["crypto-earn","Crypto Earn (produk simpanan kripto)","Crypto Earn adalah kategori produk di bursa yang memberi imbal hasil atas aset kripto yang Anda simpan, misalnya simpanan fleksibel, simpanan berjangka, staking, atau produk terstruktur."],["funding-rate","Funding rate","Funding rate adalah pembayaran berkala antara trader posisi long dan short di kontrak perpetual yang menjaga harga kontrak tetap dekat dengan harga spot."]],"lesson":null,"coin":null,"tool":null,"cta":false},"algorithmic-stablecoin":{"slug":"algorithmic-stablecoin","cat":"stablecoins","en":"Algorithmic stablecoin","contentLocale":"id","term":"Stablecoin algoritmik (algorithmic stablecoin)","aka":["algorithmic stablecoin","algo stablecoin"],"short":"Stablecoin algoritmik adalah stablecoin yang mencoba menjaga patokan harga lewat aturan kode dan insentif pasar, bukan lewat cadangan kas penuh atau jaminan berlebih.","body":[["Idenya: ketika harga di atas 1 dolar, sistem menambah pasokan; ketika di bawah 1 dolar, sistem mengurangi pasokan. Banyak desain memakai token pendamping. Misalnya, pengguna bisa menukar 1 ",["stablecoin","stablecoin"]," dengan token pendamping senilai 1 dolar, sehingga ada insentif ",["arbitrase","arbitrage"]," untuk mengembalikan harga ke patokan."],"Masalahnya, mekanisme ini bergantung pada kepercayaan dan nilai token pendamping. Saat panik, orang menukar stablecoin ke token pendamping lalu menjualnya. Harga token pendamping jatuh, pasokan membengkak, dan kepercayaan makin hilang. Siklus ini disebut death spiral. Runtuhnya UST milik Terra pada Mei 2022 adalah contoh paling terkenal.","Karena itu, banyak proyek baru memakai model hibrida: sebagian dijamin aset, sebagian dikendalikan algoritma. Sebelum memegang stablecoin seperti ini, cek apa yang sebenarnya menjamin nilainya dan apa yang terjadi saat terjadi penarikan besar."],"example":["Misalkan stablecoin algoritmik turun ke 0,95 dolar. Sistem mengizinkan Anda menukar 1 koin dengan token pendamping senilai 1 dolar. Anda membeli 1.000 koin seharga 950 dolar, menukarnya, lalu menjual token pendamping seharga 1.000 dolar, untung 50. Arbitrase seperti ini seharusnya mendorong harga naik. Namun jika harga token pendamping turun 30% saat Anda menjualnya, Anda hanya menerima sekitar 700 dolar dan rugi 250. Ketika banyak orang mengalami hal yang sama, tekanan jual memperburuk ",["depeg","depeg"],"."],"mistakes":["Tergiur imbal hasil tinggi tanpa bertanya dari mana imbal hasil itu dibayar.","Menyamakan stablecoin algoritmik dengan stablecoin yang didukung kas penuh.","Mengira arbitrase pasti mengembalikan patokan dalam kondisi panik."],"faq":[{"q":"Apa yang terjadi pada UST Terra?","a":"Pada Mei 2022, UST kehilangan patokannya dan token pendampingnya, LUNA, jatuh hampir ke nol karena pasokannya membengkak. Kejadian ini menghapus nilai puluhan miliar dolar dan membuat regulator di banyak negara memperketat aturan stablecoin."},{"q":"Apakah semua stablecoin algoritmik pasti gagal?","a":"Tidak pasti, tetapi desain yang hanya mengandalkan insentif tanpa cadangan nyata terbukti rapuh saat panik. Itu sebabnya banyak proyek beralih ke model hibrida dengan jaminan."}],"title":"Apa itu stablecoin algoritmik? Cara kerja dan risikonya","description":"Pelajari cara kerja stablecoin algoritmik, kenapa bisa terjadi death spiral seperti UST Terra, dan risikonya.","related":[["depeg","Depeg","Depeg adalah kondisi ketika harga stablecoin atau aset yang dipatok menyimpang cukup jauh dari nilai patokannya, misalnya USDT atau USDC diperdagangkan jauh di bawah 1 dolar AS."],["stablecoin","Stablecoin","Stablecoin adalah aset kripto yang dirancang menjaga nilai stabil terhadap aset acuan, biasanya 1 dolar AS, seperti USDT dan USDC, sehingga dipakai sebagai alat tukar dan tempat parkir dana di pasar kripto."],["crypto-backed-stablecoin","Stablecoin berjaminan kripto (crypto-backed stablecoin)","Stablecoin berjaminan kripto adalah stablecoin yang dicetak dengan mengunci aset kripto seperti ETH sebagai jaminan dengan nilai lebih besar daripada stablecoin yang diterbitkan."],["synthetic-dollar","Dolar sintetis (synthetic dollar)","Dolar sintetis adalah token bernilai sekitar 1 dolar yang dijaga lewat posisi delta-netral, yaitu memegang aset kripto sekaligus membuka posisi short dengan ukuran sama di kontrak berjangka perpetual."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"Apakah USDT itu dolar? Mengapa sering muncul saat beli kripto?"},"coin":null,"tool":null,"cta":false}});
